<script setup lang="ts">
import { ArrowUpRight, Camera, Plus, X } from 'lucide-vue-next'
definePageMeta({ layout: 'app' })
const api = useApi()
const { data: jobs, refresh } = await useAsyncData('home-jobs', () => api.request<any[]>('/portal/jobs').catch(() => []))
const open = ref(false); const saving = ref(false)
const form = reactive({ address: '', city: 'Katy, TX', propertyType: 'residential', issue: '', phone: '', videoUrl: '' })
async function create() { saving.value = true; try { await api.request('/portal/jobs', { method: 'POST', body: form }); open.value = false; await refresh() } finally { saving.value = false } }
</script>
<template>
  <div><PortalHeader><template #eyebrow>Vomtek Home</template><template #title>Home line jobs.</template><template #subtitle>Camera-reviewed reports, contractor bids and escrow for residential and property lines.</template><template #actions><button class="btn btn-dark !min-h-9 !px-3 !text-[10px]" @click="open = true"><Plus :size="13" /> New job</button></template></PortalHeader>
    <div class="grid gap-4 md:grid-cols-2 xl:grid-cols-3"><NuxtLink v-for="j in jobs" :key="j._id" :to="`/app/home/${j._id}`" class="group rounded-xl border border-ink/12 bg-bone p-5 transition-colors hover:border-ink/30"><div class="flex items-start justify-between"><span class="flex size-9 items-center justify-center rounded-lg bg-signal/15 text-signal-deep"><Camera :size="16" /></span><StatusPill :status="j.status" /></div><p class="mt-5 font-mono text-[8.5px] uppercase tracking-[.08em] text-ink/75">{{ j.ref }}</p><h3 class="mt-1 font-display text-[22px] leading-tight tracking-[-.03em]">{{ j.address }}</h3><p class="mt-2 line-clamp-2 text-[12px] leading-relaxed text-ink/75">{{ j.issue }}</p><div class="mt-4 flex items-center justify-between border-t border-ink/10 pt-3"><span class="font-mono text-[9px] text-ink/75">{{ j.defects?.length || 0 }} findings</span><span class="inline-flex items-center gap-1 font-mono text-[9px] uppercase tracking-[.06em] text-signal-deep">Open <ArrowUpRight :size="11" /></span></div></NuxtLink><button class="flex min-h-52 flex-col items-center justify-center rounded-xl border border-dashed border-ink/20 text-ink/75 hover:border-ink/40 hover:text-ink" @click="open = true"><Plus :size="20" /><span class="mt-2 text-[12px]">Start a home line review</span></button></div>
    <div v-if="open" class="fixed inset-0 z-[70] flex items-start justify-center overflow-y-auto bg-ink/45 p-4 backdrop-blur-sm md:items-center" @click.self="open = false"><div class="w-full max-w-lg rounded-2xl bg-bone p-6"><div class="flex items-start justify-between"><div><p class="label-mono text-signal-deep">New home job</p><h2 class="mt-1 font-display text-[28px]">Tell us what is happening.</h2></div><button @click="open = false"><X :size="18" /></button></div><form class="mt-5 grid gap-4 sm:grid-cols-2" @submit.prevent="create"><div class="sm:col-span-2"><label class="field-label">Property address</label><input v-model="form.address" required class="field" placeholder="1420 Cedar Ridge Dr"></div><div><label class="field-label">City</label><input v-model="form.city" class="field"></div><div><label class="field-label">Phone</label><input v-model="form.phone" class="field"></div><div class="sm:col-span-2"><label class="field-label">What is the issue?</label><textarea v-model="form.issue" required rows="3" class="field resize-none" placeholder="Recurring backup, slow drain, smell, leak…" /></div><div class="sm:col-span-2"><label class="field-label">Video / footage reference (optional)</label><input v-model="form.videoUrl" class="field" placeholder="Filename or link"></div><div class="sm:col-span-2 flex justify-end gap-2"><button type="button" class="btn btn-outline" @click="open = false">Cancel</button><button class="btn btn-dark" :disabled="saving">{{ saving ? 'Creating…' : 'Create job' }}</button></div></form></div></div>
  </div>
</template>
